import * as T from 'three';
const mat=(color,roughness=.72)=>new T.MeshStandardMaterial({color,roughness});
function ball(parent,name,pos,scale,material){const o=new T.Mesh(new T.SphereGeometry(1,20,14),material);o.name=name;o.position.set(...pos);o.scale.set(...scale);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function capsule(parent,name,a,b,r,material){const A=new T.Vector3(...a),B=new T.Vector3(...b),d=B.clone().sub(A);const mesh=new T.Mesh(new T.CapsuleGeometry(r,Math.max(.01,d.length()-2*r),5,12),material);mesh.name=name;mesh.position.copy(A.add(B).multiplyScalar(.5));mesh.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());mesh.castShadow=true;parent.add(mesh);return mesh;}
export function createFighter(id){const root=new T.Group();root.name=id;const skin=mat(id==='pedro'?0xb97651:0xc98768),shirt=mat(id==='pedro'?0x258b51:0xe8d6bc),pants=mat(id==='pedro'?0x353746:0x722d54),shoe=mat(0x29232a),hair=mat(id==='pedro'?0x33251d:0x38242b),accent=mat(id==='pedro'?0xd8c39a:0xf0b7bf);
  const pelvis=new T.Group();pelvis.position.y=.98;root.add(pelvis);
  ball(pelvis,'torso',[0,.55,0],[.43,.62,.28],shirt);ball(pelvis,'hip',[0,.03,0],[.36,.25,.27],pants);ball(pelvis,'neck',[0,1.14,0],[.13,.17,.14],skin);ball(pelvis,'head',[0,1.48,0],[.31,.39,.29],skin);ball(pelvis,'hair',[0,1.74,-.015],[.32,.18,.3],hair);ball(pelvis,'nose',[0,1.46,.28],[.065,.075,.06],skin);for(const s of [-1,1]){ball(pelvis,'eye',[s*.11,1.53,.266],[.035,.045,.018],mat(0x201816));ball(pelvis,'ear',[s*.31,1.48,0],[.065,.1,.07],skin);}
  const limbs={};for(const side of [-1,1]){const arm=new T.Group();arm.position.set(side*.43,1.02,0);pelvis.add(arm);limbs[side<0?'armL':'armR']=arm;capsule(arm,'upperArm',[0,0,0],[side*.08,-.36,.03],.14,shirt);const fore=new T.Group();fore.position.set(side*.08,-.35,.03);arm.add(fore);limbs[side<0?'foreL':'foreR']=fore;capsule(fore,'forearm',[0,0,0],[side*.03,-.34,.06],.115,skin);ball(fore,'hand',[side*.03,-.37,.08],[.13,.12,.13],skin);
    const leg=new T.Group();leg.position.set(side*.19,.08,0);pelvis.add(leg);limbs[side<0?'legL':'legR']=leg;capsule(leg,'thigh',[0,0,0],[0,-.43,0],.19,pants);const shin=new T.Group();shin.position.y=-.42;leg.add(shin);limbs[side<0?'shinL':'shinR']=shin;capsule(shin,'shin',[0,0,0],[0,-.43,.01],.135,pants);ball(shin,'shoe',[0,-.46,.09],[.19,.1,.29],shoe);}
  if(id==='paula'){ball(pelvis,'ponytail',[0,1.61,-.29],[.16,.38,.15],hair).rotation.x=-.5;ball(pelvis,'scarf',[0,.92,.01],[.38,.13,.29],accent);}else{ball(pelvis,'beard',[0,1.32,.17],[.23,.2,.15],hair);ball(pelvis,'belt',[0,.12,.01],[.36,.065,.29],accent);}
  root.userData={pelvis,limbs,id,baseY:0};return root;}
export function animateFighter(root,f,dt,time){const {pelvis,limbs}=root.userData;const moving=Math.abs(f.vx)>.18,run=Math.abs(f.vx)>3.1;pelvis.position.y=.98+(moving?Math.abs(Math.sin(time*(run?14:8)))*.045:Math.sin(time*3)*.018);pelvis.rotation.z=f.state==='hit'?-.2*f.facing:0;const attack=f.attack?.kind;const phase=f.attack?Math.min(1,f.attack.time/(f.attack.move.startup+f.attack.move.active+f.attack.move.recovery)):0;
  for(const [i,key] of ['legL','legR'].entries()){const swing=moving?Math.sin(time*(run?14:8)+i*Math.PI)*.42:0;limbs[key].rotation.x=f.y>0?-.3:swing;if(attack==='kick'&&key===(f.facing>0?'legR':'legL'))limbs[key].rotation.x=-Math.sin(phase*Math.PI)*1.15;limbs[i?'shinR':'shinL'].rotation.x=attack==='kick'?.35:0;}
  for(const [i,key] of ['armL','armR'].entries()){const front=(i===1)===(f.facing>0);limbs[key].rotation.x=f.block?(front?-.8:-.3):Math.sin(time*2+i)*.04;limbs[key].rotation.z=f.block?(front?-.6:.4):0;if(attack==='punch'&&front)limbs[key].rotation.x=-Math.sin(phase*Math.PI)*1.3;if(attack==='special'&&front)limbs[key].rotation.x=-Math.sin(phase*Math.PI)*1.1;limbs[i?'foreR':'foreL'].rotation.x=attack==='punch'&&front?.2:0;}
  root.rotation.y=f.facing===1?Math.PI/2:-Math.PI/2;root.position.set(f.x,f.y,f.z);root.scale.setScalar(f.crouch?.88:1);}
